const H = (st, px) => Math.round(px * st.hscale);
const tint = (pct, v = "primary") => `color-mix(in oklab,var(--${v}) ${pct}%,var(--surface))`;
const sbadge = (t, k) => `<span style="display:inline-flex;align-items:center;gap:4px;height:20px;padding:0 8px;border-radius:999px;font:600 11px var(--font-b);white-space:nowrap;background:color-mix(in oklab,var(--${k}) 14%,var(--surface));color:color-mix(in oklab,var(--${k}) 78%,var(--text))">${t}</span>`;
const scrim = `<div style="position:absolute;inset:0;background:color-mix(in oklab,var(--ink) 50%,transparent)"></div>`;
const kbd = (t) => `<span style="display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 5px;border:1px solid var(--border);border-bottom-width:2px;border-radius:5px;font:600 11px var(--font-b);color:var(--muted);background:var(--bg)">${t}</span>`;
const radio = (on, danger) => `<span style="flex:none;width:18px;height:18px;border-radius:50%;border:2px solid ${on ? `var(--${danger ? "danger" : "primary"})` : "var(--border)"};display:grid;place-items:center">${on ? `<span style="width:8px;height:8px;border-radius:50%;background:var(--${danger ? "danger" : "primary"})"></span>` : ""}</span>`;
const sw = (on) => `<span role="switch" aria-checked="${on}" style="flex:none;width:34px;height:20px;border-radius:999px;position:relative;background:${on ? "var(--primary)" : "color-mix(in oklab,var(--muted) 30%,var(--surface))"}"><span style="position:absolute;top:2px;left:${on ? 16 : 2}px;width:16px;height:16px;border-radius:50%;background:${on ? "var(--on-primary)" : "var(--surface)"};box-shadow:0 1px 2px rgba(0,0,0,.25)"></span></span>`;
const bar = (pct, h = 6, v = "primary") => `<div style="height:${h}px;border-radius:9px;background:${tint(16, v)};overflow:hidden"><div style="width:${pct}%;height:100%;border-radius:9px;background:var(--${v})"></div></div>`;
const iconTile = (i, s = 36, v = "primary") => `<span style="flex:none;width:${s}px;height:${s}px;border-radius:var(--radius);display:grid;place-items:center;background:${tint(14, v)};color:color-mix(in oklab,var(--${v}) 80%,var(--text))">${ic(i, Math.round(s * 0.5))}</span>`;

/* ================================================================= first-run (checklist | blank-slate) */
const FW_NAV = [["home", "Home"], ["grid", "Projects"], ["check", "My tasks"], ["doc", "Docs"], ["folder", "Files"], ["users", "Team"], ["gear", "Settings"]];
const FW_TABS = [["home", "Home"], ["grid", "Projects"], ["check", "Tasks"], ["gear", "Settings"]];
const fwTop = (title, right = "") => `<div class="top"><div style="font-weight:600;font-size:15px">${title}</div><div class="search">${ic("search", 15)}Search Fernway${kbd("⌘K")}</div>${right}<span style="display:flex;color:var(--muted)">${ic("bell", 19)}</span></div>`;

const STEPS = [
  ["users", "Invite your teammates", "3 invites sent to Teodora, Sam and Lin", "done", ""],
  ["bell", "Set up notifications", "Daily digest at 9:00, mentions on mobile", "done", ""],
  ["grid", "Create your first project", "A project holds tasks, docs and files. Most teams start with a client job or a launch.", "next", "2 min"],
  ["calendar", "Connect your calendar", "Show due dates next to your meetings", "todo", "1 min"],
  ["upload", "Import tasks", "From a CSV, a spreadsheet or another task app’s export", "todo", "3 min"],
];
const stepDot = (s, n, sz = 26) => s === "done"
  ? `<span style="flex:none;width:${sz}px;height:${sz}px;border-radius:50%;display:grid;place-items:center;background:var(--primary);color:var(--on-primary)">${ic("check", Math.round(sz * 0.55))}</span>`
  : `<span style="flex:none;width:${sz}px;height:${sz}px;border-radius:50%;display:grid;place-items:center;font:600 12px var(--font-b);border:2px solid ${s === "next" ? "var(--primary)" : "var(--border)"};color:${s === "next" ? "var(--primary)" : "var(--muted)"}">${n}</span>`;
const ring = (pct, s, label) => {
  const r = s / 2 - 5, c = 2 * Math.PI * r;
  return `<svg width="${s}" height="${s}" viewBox="0 0 ${s} ${s}" style="flex:none"><circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="${tint(18)}" stroke-width="6"/><circle cx="${s / 2}" cy="${s / 2}" r="${r}" fill="none" stroke="var(--primary)" stroke-width="6" stroke-linecap="round" stroke-dasharray="${(c * pct / 100).toFixed(1)} ${c.toFixed(1)}" transform="rotate(-90 ${s / 2} ${s / 2})"/><text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle" style="font:600 ${Math.round(s / 4.6)}px var(--font-b);fill:var(--text)">${label}</text></svg>`;
};
