// Illustrative "photos": natural-tone gradients and SVG shapes (fixed colours are allowed for artwork).
const PH = [
  ["#f4d6ae", "#f8ead6", "#b98b72", "#6e4e43", "#fff3dc", "hills"], ["#a9cbe0", "#e6f0f4", "#6f93a8", "#2f5470", "#ffffff", "sea"],
  ["#cfdcbf", "#f2eedc", "#8da27c", "#4a6847", "#f7e6b0", "trees"], ["#283653", "#6c6f93", "#3b4062", "#1d2136", "#f3d58b", "city"],
  ["#ecd2bd", "#f6e8dc", "#cc9d80", "#91624b", "#fff8ee", "dunes"], ["#e3d5c4", "#f1e9dd", "#c08d5c", "#7a4f2e", "#f6efe4", "loaf"],
  ["#c7d3dc", "#e9eef1", "#9aa8b4", "#55606b", "#e9d6c4", "portrait"],
];
const photo = (k, flip) => {
  const [a, b, f, n, s, kind] = PH[k % PH.length];
  const g = {
    hills: `<circle cx="118" cy="38" r="14" fill="${s}"/><path d="M0 84C30 60 60 62 90 78s50-8 70-14v56H0z" fill="${f}"/><path d="M0 100c40-18 80-8 110-2s40-6 50-8v30H0z" fill="${n}"/>`,
    sea: `<circle cx="40" cy="44" r="12" fill="${s}" opacity=".9"/><rect y="74" width="160" height="46" fill="${f}"/><path d="M0 86h160M0 97h160M0 108h160" stroke="${s}" stroke-opacity=".35"/><path d="M90 72h36l-6 9h-24z" fill="${n}"/><path d="M106 72V46l15 24z" fill="${s}"/>`,
    trees: `<rect y="96" width="160" height="24" fill="${n}"/>${[16, 42, 68, 96, 124, 150].map((x, i) => `<path d="M${x} ${56 + (i % 2) * 12}l15 ${42 - (i % 2) * 12}h-30z" fill="${i % 2 ? f : n}"/>`).join("")}`,
    city: `<circle cx="126" cy="28" r="9" fill="${s}"/>${[[4, 58, 22], [28, 40, 18], [48, 66, 26], [76, 30, 20], [98, 52, 24], [124, 44, 32]].map(([x, y, w], i) => `<rect x="${x}" y="${y}" width="${w}" height="${120 - y}" fill="${i % 2 ? f : n}"/>${[0, 1, 2].map((r) => `<rect x="${x + 5}" y="${y + 8 + r * 14}" width="4" height="5" fill="${s}" opacity="${(i + r) % 3 ? 0.8 : 0.2}"/>`).join("")}`).join("")}`,
    dunes: `<circle cx="34" cy="36" r="13" fill="${s}"/><path d="M0 80q50-26 100 0t60-6v46H0z" fill="${f}"/><path d="M0 104q60-22 120-4t40-2v22H0z" fill="${n}"/>`,
    loaf: `<rect y="88" width="160" height="32" fill="${f}" opacity=".45"/><ellipse cx="80" cy="82" rx="48" ry="24" fill="${f}"/><path d="M54 76q8-11 16 0M74 72q8-11 16 0M94 76q8-11 16 0" stroke="${n}" stroke-width="3" fill="none"/><circle cx="132" cy="96" r="9" fill="${n}" opacity=".7"/>`,
    portrait: `<circle cx="80" cy="50" r="20" fill="${f}"/><path d="M38 120c4-26 20-38 42-38s38 12 42 38z" fill="${n}"/>`,
  }[kind];
  return `<div style="position:absolute;inset:0;background:linear-gradient(180deg,${a},${b})"><svg viewBox="0 0 160 120" preserveAspectRatio="xMidYMid slice" width="100%" height="100%" style="display:block${flip ? ";transform:scaleX(-1)" : ""}">${g}</svg></div>`;
};
